type EnvironmentSettings = { provider: ModelProviderId; baseUrl: string; model: string; apiKeyConfigured: boolean };
type LocalEmbeddingModelStatus = { state: "pending" | "downloading" | "verifying" | "retrying" | "importing" | "ready" | "error"; onnxState: "pending" | "parsing" | "ready" | "failed"; downloadedBytes: number; totalBytes: number | null; attempt: number; error?: string };
type LatestRelease = { latestVersion: string; url: string; releaseNotes: string };
type AutoBackupMode = "realtime" | "daily" | "weekly";
type AutoBackupOverflowPolicy = "delete-oldest" | "pause";
type AutoBackupStatus = { directory: string; totalBytes: number; count: number; lastBackupAt: string | null; pausedReason: string | null; minimumStorageMb: number };
type NetworkDiagnostic = { id: "network" | "github" | "huggingface"; label: string; ok: boolean; status?: number; durationMs: number; failureKind?: "timeout" | "dns" | "tls" | "proxy" | "connection" | "http" | "unknown"; detail: string };
type NetworkDiagnosticLayer = { id: "electron" | "service"; label: string; transport: string; checks: NetworkDiagnostic[] };
type NetworkDiagnostics = { layers: NetworkDiagnosticLayer[]; guidance?: string };
type CloudSyncConfig = { enabled: boolean; mode: "automatic" | "manual"; intervalMinutes: 15 | 30 | 60 | 180 | 360 | 720 | 1440; url: string; directory: string; username: string; maxStorageMb: number; overflowPolicy: "delete-oldest" | "pause"; historyLimit: number };
type CloudSyncStatus = { available: boolean; passwordConfigured: boolean; lastSyncedAt: string | null; nextSyncAt: string | null; pausedReason: string | null; lastError: string | null; remoteBytes: number; remoteCount: number; lastSummary: string | null };
type SupabaseSyncStatus = { configured: boolean; enabled: boolean; signedIn: boolean; email: string | null; lastSyncedAt: string | null; nextSyncAt: string | null; lastError: string | null; summary: string | null; pendingChoice: boolean };
const CUSTOM_MODEL_OPTION = "__custom_model__";

function sizeLabel(bytes: number) { return bytes < 1024 * 1024 ? `${Math.round(bytes / 1024)} KB` : `${(bytes / 1024 / 1024).toFixed(1)} MB`; }

