  const [supabaseStatus, setSupabaseStatus] = useState<SupabaseSyncStatus | null>(null); const [supabaseHistoryOpen, setSupabaseHistoryOpen] = useState(false); const [supabaseUrl, setSupabaseUrl] = useState(""); const [supabaseAnonKey, setSupabaseAnonKey] = useState(""); const [editingSupabaseProject, setEditingSupabaseProject] = useState(false); const [supabaseEmail, setSupabaseEmail] = useState(""); const [supabaseCode, setSupabaseCode] = useState(""); const [supabaseBusy, setSupabaseBusy] = useState(false); const [supabaseNotice, setSupabaseNotice] = useState(""); const [syncGuideAnchor, setSyncGuideAnchor] = useState<string | null>(null);
