  const saveSupabaseProjectConfig = async () => { setSupabaseBusy(true); setSupabaseNotice(""); try { const data = await fetchJson<{ status: SupabaseSyncStatus }>("/api/supabase-sync", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "configure", url: supabaseUrl, key: supabaseAnonKey }), label: "保存 Supabase 配置" }); setSupabaseStatus(data.status); setSupabaseAnonKey(""); setEditingSupabaseProject(false); setSupabaseNotice("Supabase 项目已保存，现在可以登录邮箱。"); } catch (error) { setSupabaseNotice(error instanceof Error ? error.message : "无法保存 Supabase 配置。"); } finally { setSupabaseBusy(false); } };
