  const save = async () => { try { const saved = await fetchJson<{ autoBackupStatus?: AutoBackupStatus }>("/api/settings", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ dailyInitialTarget, dailyReviewTarget, dailyReportRetentionDays, answerComparisonMode, embeddingModelSource, stabilityRarityPreset, tagDisplayLanguage, autoBackupEnabled, autoBackupMode, autoBackupMaxStorageMb, autoBackupOverflowPolicy }), label: "保存基本设置" }); setAutoBackupStatus(saved.autoBackupStatus ?? autoBackupStatus); setNotice("基本设置已保存。"); } catch (error) { setNotice(error instanceof Error ? error.message : "无法保存基本设置。"); } };
